#!/usr/bin/env python3
"""
pin-requirements.py - turn pinned requirements into a hash-pinned requirements file.

Why this exists: a rule such as SEC-28 asks for `name==version --hash=sha256:...` so that
a substituted or tampered artifact fails the install. Computing those hashes by hand is
repetitive and error-prone, so this script does it deterministically.

It reads the PyPI JSON API (https://pypi.org/pypi/<name>/<version>/json), which lists every
published file for that release together with its sha256 digest, and writes a requirements
file where each pin carries every hash pip may legitimately match.

Usage:
    python pin-requirements.py --file requirements.in --out requirements.txt
    python pin-requirements.py --file requirements.in --out requirements.txt --only httpx,fastapi
    python pin-requirements.py --package httpx==0.28.1

Requirements: Python 3.8+, standard library only. No changes are made to the system
environment; it only reads the PyPI JSON API and writes the file you name.
"""

import argparse
import json
import sys
import urllib.error
import urllib.request

PYPI_JSON = "https://pypi.org/pypi/{name}/{version}/json"
USER_AGENT = "engineering-standards-skill/pin-requirements"


def parse_pin(line):
    """Return (name, version) for a 'name==version' requirement line, or None."""
    line = line.split("#", 1)[0].split(";", 1)[0].strip()
    if not line or line.startswith("-"):
        return None
    if "==" not in line:
        return None
    name, version = line.split("==", 1)
    name = name.strip()
    version = version.strip()
    # keep the extras marker out of the name, e.g. requests[socks]==2.32.3
    if "[" in name:
        name = name.split("[", 1)[0]
    if not name or not version:
        return None
    return name, version


def fetch_hashes(name, version, timeout=30):
    url = PYPI_JSON.format(name=name, version=version)
    request = urllib.request.Request(url, headers={"User-Agent": USER_AGENT, "Accept": "application/json"})
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as err:
        raise RuntimeError("{0}=={1}: PyPI returned HTTP {2}".format(name, version, err.code))
    except urllib.error.URLError as err:
        raise RuntimeError("{0}=={1}: {2}".format(name, version, err.reason))

    digests = set()
    for item in payload.get("urls", []):
        digest = (item.get("digests") or {}).get("sha256")
        if digest:
            digests.add(digest)
    if not digests:
        raise RuntimeError("{0}=={1}: no sha256 digest published for this release".format(name, version))
    return sorted(digests)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Generate a hash-pinned requirements file from PyPI.")
    parser.add_argument("--file", help="input requirements file with name==version pins")
    parser.add_argument("--out", help="output requirements file (default: stdout)")
    parser.add_argument("--package", help="single name==version to hash, ignoring --file")
    parser.add_argument("--only", help="comma separated list of package names to include")
    parser.add_argument("--timeout", type=int, default=30)
    args = parser.parse_args(argv)

    pins = []
    if args.package:
        parsed = parse_pin(args.package)
        if not parsed:
            print("error: --package must look like name==version", file=sys.stderr)
            return 2
        pins.append(parsed)
    else:
        if not args.file:
            parser.error("provide --file or --package")
        with open(args.file, "r", encoding="utf-8") as handle:
            for line in handle:
                parsed = parse_pin(line)
                if parsed:
                    pins.append(parsed)

    if args.only:
        wanted = {name.strip().lower() for name in args.only.split(",") if name.strip()}
        pins = [p for p in pins if p[0].lower() in wanted]

    if not pins:
        print("error: no 'name==version' pins found in the input", file=sys.stderr)
        return 2

    lines = ["# hash-pinned requirements generated by pin-requirements.py",
             "# verify the source: https://pypi.org/project/<name>/<version>/",
             ""]
    failures = []
    for name, version in pins:
        try:
            digests = fetch_hashes(name, version, timeout=args.timeout)
        except RuntimeError as err:
            failures.append(str(err))
            continue
        lines.append("{0}=={1} \\".format(name, version))
        for index, digest in enumerate(digests):
            suffix = "" if index == len(digests) - 1 else " \\"
            lines.append("    --hash=sha256:{0}{1}".format(digest, suffix))
        lines.append("")

    if failures:
        print("error: could not resolve {0} package(s):".format(len(failures)), file=sys.stderr)
        for failure in failures:
            print("  " + failure, file=sys.stderr)

    body = "\n".join(lines)
    if args.out:
        with open(args.out, "w", encoding="utf-8") as handle:
            handle.write(body + "\n")
        print("wrote {0} with {1} pinned package(s)".format(args.out, len(pins) - len(failures)))
    else:
        print(body)

    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
